\set ON_ERROR_STOP on
begin;
update public.profiles set ui_preferences='{"account":{"keep":true},"interface":{"revision":8,"config":{"brandName":"Activo"}}}' where id='22222222-2222-4222-8222-222222222222';
set role authenticated;
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222"}',true);
select public.totus_interface_styles('create','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Mi estilo','{"primary":"#112233","borderWidth":2}',0);
select public.qa_denied('select public.totus_interface_styles(''rename'',''aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'',''Viejo'',null,0)','otra ventana');
select public.qa_denied('select public.totus_interface_styles(''create'',''bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'',''Mi estilo'',''{}'',1)','ese nombre');
select public.qa_denied('select public.totus_interface_styles(''replace'',''aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'',''Mi estilo'',''{"tax_id":"BAD"}'',1)','Campo');
select public.totus_interface_styles('rename','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Renombrado',null,1);
select public.totus_interface_styles('replace','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Renombrado','{"primary":"#445566"}',2);
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333"}',true);
select public.qa_denied('select public.totus_interface_styles(''remove'',''aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'',null,null,0)','No se encontró');
select public.totus_interface_styles('create','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','Mi estilo','{}',0);
reset role;
select public.qa_assert((select ui_preferences#>>'{interface,config,brandName}' from public.profiles where id='22222222-2222-4222-8222-222222222222')='Activo','Library never applies interface');
select public.qa_assert((select ui_preferences#>>'{account,keep}' from public.profiles where id='22222222-2222-4222-8222-222222222222')='true','Other preferences preserved');
select public.qa_assert((select ui_preferences#>>'{interface_styles,items,0,config,primary}' from public.profiles where id='22222222-2222-4222-8222-222222222222')='#445566','Replace saved configuration');
set role authenticated;
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222"}',true);
select public.totus_save_my_appearance('{"primary":"#abcdef"}',8);
select public.totus_interface_styles('remove','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',null,null,3);
reset role;
select public.qa_assert((select jsonb_array_length(ui_preferences#>'{interface_styles,items}') from public.profiles where id='22222222-2222-4222-8222-222222222222')=0,'Remove only owned style');
select public.qa_assert((select ui_preferences#>>'{interface,config,primary}' from public.profiles where id='22222222-2222-4222-8222-222222222222')='#abcdef','Remove leaves active appearance intact');
select public.qa_assert((select jsonb_array_length(ui_preferences#>'{interface_styles,items}') from public.profiles where id='33333333-3333-4333-8333-333333333333')=1,'Other user library intact');
set role anon;
select public.qa_denied('select public.totus_interface_styles(''create'',''aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'',''No'',''{}'',0)','permission denied');
reset role;
rollback;
